import ast

def parse(value: str):
    return ast.literal_eval(value)

import json

def parse(value: str):
    return json.loads(value)

ALLOWED_COMMANDS = {"status": ("git", "status")}

def command(name: str):
    return ALLOWED_COMMANDS[name]

import yaml

def parse(value: str):
    return yaml.safe_load(value)

import hashlib

def digest(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()

import tempfile

def temporary():
    return tempfile.NamedTemporaryFile(delete=True)

import requests

def fetch(url: str):
    return requests.get(url, timeout=5)

import pickle

def parse(value: bytes):
    return pickle.loads(value)

import subprocess

def execute(command: str):
    return subprocess.run(command, shell=True)

import yaml

def parse(value: str):
    return yaml.load(value, Loader=yaml.Loader)

import hashlib

def digest(value: bytes) -> str:
    return hashlib.md5(value).hexdigest()

import tempfile

def temporary():
    return tempfile.mktemp()

import requests

def fetch(url: str):
    return requests.get(url, verify=False, timeout=5)
